    it.each([
        [PLANS.BUNDLE, PLAN_NAMES[PLANS.BUNDLE]],
        [PLANS.DRIVE, PLAN_NAMES[PLANS.DRIVE]],
        [PLANS.BUNDLE_PRO_2024, PLAN_NAMES[PLANS.BUNDLE_PRO_2024]],
